PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA synchronous=FULL;
PRAGMA secure_delete=ON;
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admins(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS config_revisions(revision INTEGER PRIMARY KEY, config_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS config_drafts(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES admins(id), base_revision INTEGER NOT NULL, config_json TEXT NOT NULL, created_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'draft',validation_json TEXT,last_check_id TEXT,applied_operation_id TEXT);
CREATE TABLE IF NOT EXISTS config_operations(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES admins(id),kind TEXT NOT NULL,status TEXT NOT NULL,draft_id TEXT, draft_revision INTEGER,config_json TEXT,result_json TEXT,error TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS config_operation_owner ON config_operations(owner_id,created_at);
CREATE TABLE IF NOT EXISTS personality_versions(revision INTEGER PRIMARY KEY, personality_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS secrets(id TEXT PRIMARY KEY, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, source_key TEXT UNIQUE, title TEXT NOT NULL, context_epoch INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), owner_id TEXT NOT NULL, client_message_id TEXT NOT NULL, input TEXT NOT NULL, config_json TEXT NOT NULL, context_epoch INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed','cancelled','interrupted')), response TEXT, error TEXT, skill_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(conversation_id,client_message_id));
CREATE INDEX IF NOT EXISTS runs_queue ON runs(status,created_at);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), run_id TEXT NOT NULL REFERENCES runs(id), role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(run_id,role));
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY, kind TEXT NOT NULL, owner_id TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('private','shared')), revision INTEGER NOT NULL, payload TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE INDEX IF NOT EXISTS record_scope ON records(kind,owner_id,visibility,deleted_at,updated_at);
CREATE VIRTUAL TABLE IF NOT EXISTS record_fts USING fts5(content, tokenize='trigram');
CREATE TRIGGER IF NOT EXISTS record_insert AFTER INSERT ON records WHEN new.deleted_at IS NULL BEGIN INSERT INTO record_fts(rowid,content) VALUES(new.rowid,new.payload); END;
CREATE TRIGGER IF NOT EXISTS record_update AFTER UPDATE ON records BEGIN DELETE FROM record_fts WHERE rowid=old.rowid; INSERT INTO record_fts(rowid,content) SELECT new.rowid,new.payload WHERE new.deleted_at IS NULL; END;
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, title TEXT NOT NULL, resource_id TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS audit_owner ON audit_events(owner_id,id);
CREATE TABLE IF NOT EXISTS channel_inbox(event_key TEXT PRIMARY KEY, channel TEXT NOT NULL, received_at INTEGER NOT NULL, run_id TEXT);
CREATE TABLE IF NOT EXISTS channel_outbox(id TEXT PRIMARY KEY, run_id TEXT NOT NULL UNIQUE REFERENCES runs(id), channel TEXT NOT NULL, target_json TEXT NOT NULL, credential_ref TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','sending','sent','failed','unknown','cancelled')), error TEXT, platform_message_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS channel_events(id TEXT PRIMARY KEY,channel TEXT NOT NULL,account_id TEXT NOT NULL,event_key TEXT NOT NULL UNIQUE,source_key TEXT NOT NULL,owner_id TEXT NOT NULL,payload_json TEXT,credential_ref TEXT NOT NULL,status TEXT NOT NULL,run_id TEXT,received_at INTEGER NOT NULL,ready_at INTEGER NOT NULL,deadline INTEGER NOT NULL,error TEXT);
CREATE INDEX IF NOT EXISTS channel_events_pending ON channel_events(status,ready_at);
CREATE TABLE IF NOT EXISTS run_targets(run_id TEXT PRIMARY KEY REFERENCES runs(id),channel TEXT NOT NULL,target_json TEXT NOT NULL,credential_ref TEXT NOT NULL,deadline INTEGER NOT NULL,account_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS delivery_parts(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),sequence INTEGER NOT NULL,kind TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL,platform_id TEXT,error TEXT,not_before INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(run_id,sequence));
CREATE TABLE IF NOT EXISTS channel_state(channel TEXT PRIMARY KEY,revision INTEGER NOT NULL,generation TEXT NOT NULL,value_json TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_jobs(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,channel TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL,account_revision INTEGER NOT NULL,secret_json TEXT,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,error TEXT);
CREATE TABLE IF NOT EXISTS source_grants(source_key TEXT PRIMARY KEY,revision INTEGER NOT NULL,capture INTEGER NOT NULL DEFAULT 0,allow_model INTEGER NOT NULL DEFAULT 0,can_sleep INTEGER NOT NULL DEFAULT 0,can_wake INTEGER NOT NULL DEFAULT 0,expires_at INTEGER,enabled_after INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS model_jobs(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,input_json TEXT,output_json TEXT,source_json TEXT NOT NULL,config_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,error TEXT,idempotency_key TEXT,UNIQUE(owner_id,idempotency_key));
CREATE INDEX IF NOT EXISTS model_jobs_pending ON model_jobs(status,created_at);
CREATE TABLE IF NOT EXISTS summaries(conversation_id TEXT PRIMARY KEY REFERENCES conversations(id),owner_id TEXT NOT NULL,revision INTEGER NOT NULL,content TEXT,source_json TEXT NOT NULL,context_epoch INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS derivations(record_id TEXT NOT NULL REFERENCES records(id),source_type TEXT NOT NULL,source_id TEXT NOT NULL,source_revision INTEGER NOT NULL,PRIMARY KEY(record_id,source_type,source_id));
CREATE TABLE IF NOT EXISTS trigger_rules(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,revision INTEGER NOT NULL,enabled INTEGER NOT NULL,rule_json TEXT NOT NULL,action_json TEXT NOT NULL,next_at INTEGER,last_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS trigger_firings(id TEXT PRIMARY KEY,trigger_id TEXT NOT NULL REFERENCES trigger_rules(id),scheduled_at INTEGER NOT NULL,status TEXT NOT NULL,result TEXT,job_id TEXT,created_at INTEGER NOT NULL,UNIQUE(trigger_id,scheduled_at));
CREATE TABLE IF NOT EXISTS rest_cycles(id TEXT PRIMARY KEY,phase TEXT NOT NULL,revision INTEGER NOT NULL,started_at INTEGER NOT NULL,wake_at INTEGER NOT NULL,drain_until INTEGER NOT NULL,completed_at INTEGER,source_key TEXT NOT NULL,result TEXT,absolute_wake_at INTEGER);
CREATE TABLE IF NOT EXISTS feature_policies(name TEXT PRIMARY KEY,revision INTEGER NOT NULL,value_json TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS media_assets(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,conversation_id TEXT NOT NULL,kind TEXT NOT NULL,mime TEXT NOT NULL,digest TEXT NOT NULL,bytes BLOB NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS run_media(run_id TEXT PRIMARY KEY REFERENCES runs(id),asset_id TEXT NOT NULL REFERENCES media_assets(id),description TEXT,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plugin_versions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,revision INTEGER NOT NULL,manifest_json TEXT NOT NULL,source TEXT NOT NULL,digest TEXT NOT NULL,status TEXT NOT NULL,test_json TEXT,approved_digest TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS relationship_proposals(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,job_id TEXT NOT NULL,source_json TEXT NOT NULL,payload TEXT,status TEXT NOT NULL,revision INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS automatic_runs(run_id TEXT PRIMARY KEY REFERENCES runs(id),kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rest_requests(request_id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,result_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS context_selections(run_id TEXT PRIMARY KEY REFERENCES runs(id),owner_id TEXT NOT NULL,details_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS local_runs(run_id TEXT PRIMARY KEY REFERENCES runs(id),kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS firing_snapshots(firing_id TEXT PRIMARY KEY REFERENCES trigger_firings(id),trigger_revision INTEGER NOT NULL,action_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_annotations(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),owner_id TEXT NOT NULL,kind TEXT NOT NULL,revision INTEGER NOT NULL,content TEXT,expires_at INTEGER,context_epoch INTEGER NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS operator_calls(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,operation_id TEXT NOT NULL,fingerprint TEXT NOT NULL,outcome TEXT NOT NULL,result_json TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS affinity_events(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,person_id TEXT NOT NULL REFERENCES records(id),delta REAL NOT NULL,reason TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS affinity_states(person_id TEXT PRIMARY KEY REFERENCES records(id),owner_id TEXT NOT NULL,score_micro INTEGER NOT NULL,settled_at INTEGER NOT NULL,last_direct_at INTEGER,remainder INTEGER NOT NULL DEFAULT 0,policy_revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS affinity_policy_history(owner_id TEXT NOT NULL,revision INTEGER NOT NULL,value_json TEXT NOT NULL,effective_at INTEGER NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(owner_id,revision));
CREATE TABLE IF NOT EXISTS affinity_event_details(event_id TEXT PRIMARY KEY REFERENCES affinity_events(id),person_id TEXT NOT NULL,event_key TEXT NOT NULL,fingerprint TEXT NOT NULL,requested_micro INTEGER NOT NULL,policy_revision INTEGER NOT NULL,kind TEXT NOT NULL,UNIQUE(person_id,event_key));
CREATE TABLE IF NOT EXISTS affinity_replay_bases(person_id TEXT PRIMARY KEY REFERENCES records(id),state_json TEXT NOT NULL,policy_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS affinity_transitions(id INTEGER PRIMARY KEY AUTOINCREMENT,person_id TEXT NOT NULL REFERENCES records(id),kind TEXT NOT NULL,unique_key TEXT NOT NULL UNIQUE,occurred_at INTEGER NOT NULL,event_id TEXT,payload_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS affinity_transition_person ON affinity_transitions(person_id,id);
CREATE TABLE IF NOT EXISTS affinity_event_sources(event_id TEXT PRIMARY KEY REFERENCES affinity_events(id),person_id TEXT NOT NULL,actor_id TEXT NOT NULL,source_type TEXT NOT NULL,source_id TEXT NOT NULL,source_revision INTEGER NOT NULL,source_policy_id TEXT,ref_json TEXT NOT NULL,identity_id TEXT,identity_revision INTEGER,invalidated_at INTEGER,direct_owner_id TEXT,direct_message_id TEXT,UNIQUE(direct_owner_id,direct_message_id));
CREATE INDEX IF NOT EXISTS affinity_event_source ON affinity_event_sources(source_type,source_id,source_revision);
CREATE INDEX IF NOT EXISTS affinity_source_policy ON affinity_event_sources(source_policy_id,invalidated_at);
CREATE TABLE IF NOT EXISTS affinity_replays(id TEXT PRIMARY KEY,person_id TEXT NOT NULL,previous_score_micro INTEGER NOT NULL,score_micro INTEGER NOT NULL,active_events INTEGER NOT NULL,reason_code TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS person_aliases(alias_id TEXT PRIMARY KEY,person_id TEXT NOT NULL REFERENCES records(id),owner_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS person_mapping_history(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,person_id TEXT NOT NULL,target_id TEXT NOT NULL,action TEXT NOT NULL,reason TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS person_profiles(person_id TEXT PRIMARY KEY REFERENCES records(id),assistant_id TEXT NOT NULL,manager_id TEXT NOT NULL,source_conversation_id TEXT,reason TEXT,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS person_profile_manager ON person_profiles(manager_id,person_id);
CREATE TABLE IF NOT EXISTS person_name_versions(person_id TEXT NOT NULL REFERENCES records(id),revision INTEGER NOT NULL,name TEXT,reason TEXT,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(person_id,revision));
CREATE TABLE IF NOT EXISTS profile_assertions(id TEXT PRIMARY KEY,person_id TEXT NOT NULL REFERENCES records(id),field TEXT NOT NULL,value_json TEXT,revision INTEGER NOT NULL,status TEXT NOT NULL,statement_kind TEXT NOT NULL,source_type TEXT NOT NULL,source_id TEXT NOT NULL,source_revision INTEGER NOT NULL,source_policy_id TEXT,ref_json TEXT NOT NULL,reason TEXT,owner_id TEXT NOT NULL,visibility TEXT NOT NULL,valid_from INTEGER,valid_until INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER);
CREATE INDEX IF NOT EXISTS profile_assertion_person ON profile_assertions(person_id,status,field);
CREATE INDEX IF NOT EXISTS profile_assertion_source ON profile_assertions(source_type,source_id,source_revision);
CREATE INDEX IF NOT EXISTS profile_assertion_policy ON profile_assertions(source_policy_id,status);
CREATE TABLE IF NOT EXISTS profile_assertion_versions(assertion_id TEXT NOT NULL REFERENCES profile_assertions(id),revision INTEGER NOT NULL,value_json TEXT,status TEXT NOT NULL,reason TEXT,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(assertion_id,revision));
CREATE TABLE IF NOT EXISTS profile_edges(id TEXT PRIMARY KEY,from_person_id TEXT NOT NULL REFERENCES records(id),to_person_id TEXT NOT NULL REFERENCES records(id),relationship_type TEXT,revision INTEGER NOT NULL,status TEXT NOT NULL,statement_kind TEXT NOT NULL,source_type TEXT NOT NULL,source_id TEXT NOT NULL,source_revision INTEGER NOT NULL,source_policy_id TEXT,ref_json TEXT NOT NULL,reason TEXT,owner_id TEXT NOT NULL,visibility TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER,legacy_record_id TEXT UNIQUE);
CREATE INDEX IF NOT EXISTS profile_edge_source ON profile_edges(source_type,source_id,source_revision);
CREATE INDEX IF NOT EXISTS profile_edge_policy ON profile_edges(source_policy_id,status);
CREATE INDEX IF NOT EXISTS profile_edge_endpoints ON profile_edges(from_person_id,to_person_id,status);
CREATE TABLE IF NOT EXISTS profile_edge_versions(edge_id TEXT NOT NULL REFERENCES profile_edges(id),revision INTEGER NOT NULL,relationship_type TEXT,status TEXT NOT NULL,reason TEXT,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(edge_id,revision));
CREATE TABLE IF NOT EXISTS profile_identities(id TEXT PRIMARY KEY,person_id TEXT NOT NULL REFERENCES records(id),conversation_id TEXT NOT NULL,owner_id TEXT NOT NULL,revision INTEGER NOT NULL,alias TEXT,reason TEXT,verified_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS profile_identity_current ON profile_identities(conversation_id) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS profile_identity_groups(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profile_group_members(person_id TEXT PRIMARY KEY REFERENCES records(id),group_id TEXT NOT NULL REFERENCES profile_identity_groups(id),linked_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profile_group_history(id INTEGER PRIMARY KEY AUTOINCREMENT,group_id TEXT NOT NULL,person_id TEXT NOT NULL,other_person_id TEXT,action TEXT NOT NULL,reason TEXT,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profile_contact_permissions(person_id TEXT PRIMARY KEY REFERENCES records(id),revision INTEGER NOT NULL,status TEXT NOT NULL,conversation_id TEXT,evidence TEXT,expires_at INTEGER,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profile_context_uses(run_id TEXT NOT NULL REFERENCES runs(id),person_id TEXT NOT NULL,person_revision INTEGER NOT NULL,assertion_id TEXT NOT NULL DEFAULT '',assertion_revision INTEGER NOT NULL DEFAULT 0,edge_id TEXT NOT NULL DEFAULT '',edge_revision INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(run_id,person_id,assertion_id,edge_id));
CREATE INDEX IF NOT EXISTS profile_context_person ON profile_context_uses(person_id,run_id);
CREATE TABLE IF NOT EXISTS profile_source_tombstones(source_type TEXT NOT NULL,source_id TEXT NOT NULL,source_revision INTEGER NOT NULL,invalidated_at INTEGER NOT NULL,PRIMARY KEY(source_type,source_id));
CREATE TABLE IF NOT EXISTS profile_expiry_marks(kind TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(kind,id,revision));
CREATE TABLE IF NOT EXISTS profile_model_jobs(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,person_id TEXT NOT NULL,person_revision INTEGER NOT NULL,source_type TEXT NOT NULL,source_id TEXT NOT NULL,source_revision INTEGER NOT NULL,source_owner_id TEXT NOT NULL,ref_json TEXT NOT NULL,targets_json TEXT NOT NULL,deletion_epoch INTEGER NOT NULL,idempotency_key TEXT NOT NULL,fingerprint TEXT NOT NULL,status TEXT NOT NULL,error_code TEXT,result_json TEXT NOT NULL DEFAULT '{}',revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(actor_id,idempotency_key));
CREATE INDEX IF NOT EXISTS profile_model_queue ON profile_model_jobs(status,created_at,id);
CREATE INDEX IF NOT EXISTS profile_model_source ON profile_model_jobs(source_type,source_id);
CREATE INDEX IF NOT EXISTS profile_model_actor ON profile_model_jobs(actor_id,person_id,created_at);
CREATE TABLE IF NOT EXISTS profile_model_attempts(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES profile_model_jobs(id),owner_id TEXT NOT NULL,status TEXT NOT NULL,config_json TEXT,input_bytes INTEGER NOT NULL,input_hash TEXT NOT NULL,output_metadata_json TEXT,error_code TEXT,started_at INTEGER NOT NULL,finished_at INTEGER);
CREATE INDEX IF NOT EXISTS profile_model_budget ON profile_model_attempts(owner_id,started_at);
CREATE INDEX IF NOT EXISTS profile_model_attempt_time ON profile_model_attempts(started_at);
CREATE INDEX IF NOT EXISTS profile_model_open_attempt ON profile_model_attempts(job_id) WHERE finished_at IS NULL;
INSERT OR IGNORE INTO metadata VALUES('profile.model.deletion_epoch','0');
CREATE TABLE IF NOT EXISTS schedule_activities(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,assistant_id TEXT NOT NULL,revision INTEGER NOT NULL,creator TEXT NOT NULL,state TEXT NOT NULL,definition_json TEXT NOT NULL,grant_revision INTEGER,approved_json TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS schedule_activity_owner ON schedule_activities(owner_id,state,updated_at);
CREATE TABLE IF NOT EXISTS schedule_exceptions(activity_id TEXT NOT NULL REFERENCES schedule_activities(id),nominal_at INTEGER NOT NULL,definition_json TEXT NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(activity_id,nominal_at));
CREATE TABLE IF NOT EXISTS schedule_revisions(activity_id TEXT NOT NULL REFERENCES schedule_activities(id),revision INTEGER NOT NULL,definition_json TEXT NOT NULL,exceptions_json TEXT NOT NULL,state TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(activity_id,revision));
CREATE TABLE IF NOT EXISTS schedule_occurrences(id TEXT PRIMARY KEY,activity_id TEXT NOT NULL REFERENCES schedule_activities(id),owner_id TEXT NOT NULL,activity_revision INTEGER NOT NULL,nominal_at INTEGER NOT NULL,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,definition_json TEXT NOT NULL,status TEXT NOT NULL,block_reason TEXT,checkpoint INTEGER NOT NULL DEFAULT 0,total_chars INTEGER,resource_hash TEXT,reading_generation INTEGER NOT NULL DEFAULT 0,result_json TEXT,started_at INTEGER,completed_at INTEGER,updated_at INTEGER NOT NULL,fence TEXT,attempts INTEGER NOT NULL DEFAULT 0,UNIQUE(activity_id,nominal_at));
CREATE INDEX IF NOT EXISTS schedule_occurrence_owner ON schedule_occurrences(owner_id,start_at);
CREATE TABLE IF NOT EXISTS schedule_idempotency(owner_id TEXT NOT NULL,request_key TEXT NOT NULL,request_hash TEXT NOT NULL,response_json TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(owner_id,request_key));
CREATE TABLE IF NOT EXISTS schedule_resources(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,title TEXT NOT NULL,content TEXT,content_hash TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,revoked_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS schedule_reading_progress(owner_id TEXT NOT NULL,resource_id TEXT NOT NULL REFERENCES schedule_resources(id),resource_hash TEXT NOT NULL,generation INTEGER NOT NULL,checkpoint INTEGER NOT NULL,total_chars INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(owner_id,resource_id,resource_hash));
CREATE TABLE IF NOT EXISTS schedule_reading_notes(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,resource_id TEXT NOT NULL,resource_hash TEXT NOT NULL,generation INTEGER NOT NULL,occurrence_id TEXT NOT NULL REFERENCES schedule_occurrences(id),start_char INTEGER NOT NULL,end_char INTEGER NOT NULL,content TEXT,model TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS schedule_grants(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,revision INTEGER NOT NULL,policy_json TEXT NOT NULL,revoked_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS schedule_plans(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,revision INTEGER NOT NULL,definition_json TEXT NOT NULL,state TEXT NOT NULL,last_planned_day TEXT,last_planned_at INTEGER,block_reason TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS schedule_budgets(owner_id TEXT NOT NULL,day TEXT NOT NULL,calls INTEGER NOT NULL DEFAULT 0,tokens INTEGER NOT NULL DEFAULT 0,changes INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(owner_id,day));
CREATE TABLE IF NOT EXISTS schedule_allocations(owner_id TEXT NOT NULL,day TEXT NOT NULL,activity_id TEXT NOT NULL,seconds INTEGER NOT NULL,PRIMARY KEY(owner_id,day,activity_id));
CREATE TABLE IF NOT EXISTS schedule_attempts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,kind TEXT NOT NULL,resource_id TEXT,activity_id TEXT,plan_id TEXT,activity_revision INTEGER,grant_revision INTEGER,status TEXT NOT NULL,config_json TEXT,input_hash TEXT,output_hash TEXT,input_bytes INTEGER,output_bytes INTEGER,reserved_tokens INTEGER NOT NULL,output_limit INTEGER NOT NULL,error_code TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,provider_fingerprint TEXT NOT NULL,model TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schedule_runtime(id INTEGER PRIMARY KEY CHECK(id=1),last_tick INTEGER NOT NULL,last_plan_tick INTEGER NOT NULL);
INSERT OR IGNORE INTO schedule_runtime VALUES(1,0,0);
CREATE TABLE IF NOT EXISTS daily_text_offers(run_id TEXT PRIMARY KEY REFERENCES runs(id),source_owner_id TEXT NOT NULL,conversation_id TEXT NOT NULL,context_epoch INTEGER NOT NULL,message_id TEXT NOT NULL,source_sequence INTEGER NOT NULL,source_scope TEXT NOT NULL,source_grant_revision INTEGER NOT NULL,offer_json TEXT NOT NULL,invalidated_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS daily_offer_source ON daily_text_offers(source_owner_id,conversation_id);
CREATE TABLE IF NOT EXISTS daily_reply_checks(run_id TEXT PRIMARY KEY REFERENCES runs(id),response_hash TEXT NOT NULL,original_reply TEXT,status TEXT NOT NULL,selection_json TEXT,input_hash TEXT,input_bytes INTEGER,output_hash TEXT,output_bytes INTEGER,finish_reason TEXT,error_code TEXT,created_at INTEGER NOT NULL,finished_at INTEGER);
CREATE TABLE IF NOT EXISTS daily_text_artifacts(activity_id TEXT PRIMARY KEY REFERENCES schedule_activities(id),manager_id TEXT NOT NULL,source_owner_id TEXT NOT NULL,conversation_id TEXT NOT NULL,source_run_id TEXT NOT NULL UNIQUE REFERENCES runs(id),activity_revision INTEGER NOT NULL,grant_id TEXT NOT NULL,grant_revision INTEGER NOT NULL,definition_hash TEXT NOT NULL,source_ref_json TEXT NOT NULL,title TEXT,content TEXT,content_hash TEXT,state TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,prepared_at INTEGER NOT NULL,saved_at INTEGER,invalidated_at INTEGER,error_code TEXT);
CREATE INDEX IF NOT EXISTS daily_artifact_actor ON daily_text_artifacts(manager_id,source_owner_id,prepared_at);
CREATE TABLE IF NOT EXISTS native_text_presentations(run_id TEXT PRIMARY KEY REFERENCES runs(id),items_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS diary_policies(id TEXT PRIMARY KEY,source_key TEXT NOT NULL,owner_id TEXT NOT NULL,manager_id TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN ('private','shared')),revision INTEGER NOT NULL,time_zone TEXT NOT NULL,enabled INTEGER NOT NULL,allow_model INTEGER NOT NULL,enabled_after INTEGER NOT NULL,grant_revision INTEGER,capture_cursor INTEGER NOT NULL DEFAULT 0,sealed_through TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(source_key,visibility));
CREATE TABLE IF NOT EXISTS diary_events(id TEXT PRIMARY KEY,policy_id TEXT NOT NULL REFERENCES diary_policies(id),owner_id TEXT NOT NULL,visibility TEXT NOT NULL,revision INTEGER NOT NULL,origin_kind TEXT NOT NULL,origin_id TEXT NOT NULL,origin_revision INTEGER NOT NULL,origin_sequence INTEGER NOT NULL,statement_type TEXT NOT NULL,content TEXT,happened_at INTEGER NOT NULL,observed_at INTEGER NOT NULL,deleted_at INTEGER,UNIQUE(policy_id,origin_kind,origin_id));
CREATE INDEX IF NOT EXISTS diary_event_period ON diary_events(policy_id,happened_at,id);
CREATE TABLE IF NOT EXISTS diary_event_versions(event_id TEXT NOT NULL REFERENCES diary_events(id),revision INTEGER NOT NULL,content TEXT,happened_at INTEGER NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(event_id,revision));
CREATE TABLE IF NOT EXISTS diary_entries(id TEXT PRIMARY KEY,policy_id TEXT NOT NULL REFERENCES diary_policies(id),assistant_id TEXT NOT NULL,owner_id TEXT NOT NULL,visibility TEXT NOT NULL,period TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,time_zone TEXT NOT NULL,revision INTEGER NOT NULL,fingerprint TEXT NOT NULL,state TEXT NOT NULL,locked INTEGER NOT NULL DEFAULT 0,deleted_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(policy_id,period,period_start,time_zone));
CREATE TABLE IF NOT EXISTS diary_entry_versions(entry_id TEXT NOT NULL REFERENCES diary_entries(id),revision INTEGER NOT NULL,facts TEXT,feelings TEXT,generator TEXT NOT NULL,fingerprint TEXT NOT NULL,complete_raw INTEGER NOT NULL,source_count INTEGER NOT NULL,observation TEXT NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(entry_id,revision));
CREATE TABLE IF NOT EXISTS diary_entry_sources(entry_id TEXT NOT NULL REFERENCES diary_entries(id),event_id TEXT NOT NULL REFERENCES diary_events(id),event_revision INTEGER NOT NULL,PRIMARY KEY(entry_id,event_id));
CREATE INDEX IF NOT EXISTS diary_source_dependents ON diary_entry_sources(event_id,entry_id);
CREATE TABLE IF NOT EXISTS diary_parents(entry_id TEXT NOT NULL REFERENCES diary_entries(id),parent_id TEXT NOT NULL REFERENCES diary_entries(id),parent_revision INTEGER NOT NULL,parent_fingerprint TEXT NOT NULL,PRIMARY KEY(entry_id,parent_id));
CREATE TABLE IF NOT EXISTS diary_tasks(entry_id TEXT PRIMARY KEY REFERENCES diary_entries(id),entry_revision INTEGER NOT NULL,policy_revision INTEGER NOT NULL,state TEXT NOT NULL,level INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,next_at INTEGER NOT NULL DEFAULT 0,error_code TEXT,requested INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,cycle_id TEXT);
CREATE TABLE IF NOT EXISTS diary_fragments(entry_id TEXT NOT NULL REFERENCES diary_entries(id),entry_revision INTEGER NOT NULL,level INTEGER NOT NULL,ordinal INTEGER NOT NULL,unit_start INTEGER NOT NULL,unit_end INTEGER NOT NULL,total_units INTEGER NOT NULL,input_digest TEXT NOT NULL,facts TEXT,feelings TEXT,model TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(entry_id,entry_revision,level,ordinal));
CREATE TABLE IF NOT EXISTS diary_attempts(id TEXT PRIMARY KEY,entry_id TEXT NOT NULL REFERENCES diary_entries(id),entry_revision INTEGER NOT NULL,policy_id TEXT NOT NULL,policy_revision INTEGER NOT NULL,status TEXT NOT NULL,config_json TEXT,input_bytes INTEGER NOT NULL,input_digest TEXT NOT NULL,output_metadata_json TEXT,error_code TEXT,started_at INTEGER NOT NULL,finished_at INTEGER);
CREATE INDEX IF NOT EXISTS diary_attempt_budget ON diary_attempts(policy_id,started_at);
CREATE TABLE IF NOT EXISTS diary_observations(id TEXT PRIMARY KEY,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS diary_requests(policy_id TEXT NOT NULL,request_key TEXT NOT NULL,request_hash TEXT NOT NULL,event_id TEXT NOT NULL,PRIMARY KEY(policy_id,request_key));
CREATE TABLE IF NOT EXISTS diary_captured_runs(policy_id TEXT NOT NULL,run_id TEXT NOT NULL,captured_at INTEGER NOT NULL,delivery_state TEXT NOT NULL,PRIMARY KEY(policy_id,run_id));
CREATE INDEX IF NOT EXISTS diary_event_origin ON diary_events(origin_kind,origin_id,deleted_at);
CREATE INDEX IF NOT EXISTS diary_entry_period ON diary_entries(policy_id,period,period_start);
CREATE VIRTUAL TABLE IF NOT EXISTS diary_event_fts USING fts5(content,tokenize='trigram');
CREATE TRIGGER IF NOT EXISTS diary_event_insert AFTER INSERT ON diary_events WHEN new.deleted_at IS NULL AND new.content IS NOT NULL BEGIN INSERT INTO diary_event_fts(rowid,content) VALUES(new.rowid,new.content); END;
CREATE TRIGGER IF NOT EXISTS diary_event_update AFTER UPDATE ON diary_events BEGIN DELETE FROM diary_event_fts WHERE rowid=old.rowid; INSERT INTO diary_event_fts(rowid,content) SELECT new.rowid,new.content WHERE new.deleted_at IS NULL AND new.content IS NOT NULL; END;
INSERT INTO diary_event_fts(diary_event_fts,rank) VALUES('secure-delete',1);
CREATE VIRTUAL TABLE IF NOT EXISTS diary_entry_fts USING fts5(content,tokenize='trigram');
CREATE TRIGGER IF NOT EXISTS diary_version_insert AFTER INSERT ON diary_entry_versions WHEN new.facts IS NOT NULL AND EXISTS(SELECT 1 FROM diary_entries e WHERE e.id=new.entry_id AND e.revision=new.revision AND e.state NOT IN ('invalidated','forgotten')) BEGIN DELETE FROM diary_entry_fts WHERE rowid=(SELECT rowid FROM diary_entries WHERE id=new.entry_id); INSERT INTO diary_entry_fts(rowid,content) SELECT rowid,new.facts||coalesce(new.feelings,'') FROM diary_entries WHERE id=new.entry_id; END;
CREATE TRIGGER IF NOT EXISTS diary_version_clear AFTER UPDATE ON diary_entry_versions WHEN new.facts IS NULL AND EXISTS(SELECT 1 FROM diary_entries WHERE id=new.entry_id AND revision=new.revision) BEGIN DELETE FROM diary_entry_fts WHERE rowid=(SELECT rowid FROM diary_entries WHERE id=new.entry_id); END;
INSERT INTO diary_entry_fts(diary_entry_fts,rank) VALUES('secure-delete',1);
CREATE TABLE IF NOT EXISTS run_publications(run_id TEXT PRIMARY KEY REFERENCES runs(id),state TEXT NOT NULL,reason TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS prompt_snapshots(run_id TEXT PRIMARY KEY REFERENCES runs(id),owner_id TEXT NOT NULL,context_epoch INTEGER NOT NULL,messages_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS prompt_snapshot_expiry ON prompt_snapshots(created_at);
CREATE INDEX IF NOT EXISTS audit_filters ON audit_events(owner_id,kind,status,id);
CREATE INDEX IF NOT EXISTS audit_expiry ON audit_events(created_at);
CREATE TRIGGER IF NOT EXISTS journal_messages AFTER INSERT ON messages BEGIN INSERT INTO audit_events(owner_id,kind,status,title,resource_id,created_at) SELECT r.owner_id,CASE new.role WHEN 'user' THEN 'input' ELSE 'output' END,'recorded',CASE new.role WHEN 'user' THEN '收到消息' ELSE '生成候选' END,new.id,new.created_at FROM runs r WHERE r.id=new.run_id; END;
CREATE TRIGGER IF NOT EXISTS journal_run_status AFTER UPDATE OF status ON runs WHEN old.status<>new.status BEGIN INSERT INTO audit_events(owner_id,kind,status,title,resource_id,created_at) VALUES(new.owner_id,'run',new.status,CASE new.status WHEN 'running' THEN '正在生成回复' WHEN 'completed' THEN '回复已生成并保存' WHEN 'cancelled' THEN '运行已取消' WHEN 'failed' THEN '运行失败' WHEN 'interrupted' THEN '运行已中断' ELSE '运行状态已更新' END,new.id,CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER IF NOT EXISTS journal_retention AFTER INSERT ON audit_events BEGIN DELETE FROM audit_events WHERE id<=new.id-20000 OR created_at<CAST(strftime('%s','now') AS INTEGER)-2592000; DELETE FROM prompt_snapshots WHERE created_at<CAST(strftime('%s','now') AS INTEGER)-2592000; END;
CREATE TRIGGER IF NOT EXISTS journal_context_removed AFTER DELETE ON audit_events WHEN old.kind='context' BEGIN DELETE FROM prompt_snapshots WHERE run_id=old.resource_id; END;
INSERT INTO record_fts(record_fts,rank) VALUES('secure-delete',1);
CREATE TABLE IF NOT EXISTS schedule_notices(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,kind TEXT NOT NULL,policy_revision INTEGER NOT NULL,activity_id TEXT,activity_revision INTEGER,nominal_at INTEGER NOT NULL,due_at INTEGER NOT NULL,definition_hash TEXT,cycle_id TEXT,status TEXT NOT NULL DEFAULT 'planned',decision_status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,postponements INTEGER NOT NULL DEFAULT 0,fence TEXT,decision TEXT NOT NULL DEFAULT 'execute',delay_minutes INTEGER NOT NULL DEFAULT 0,error_code TEXT,revision INTEGER NOT NULL DEFAULT 1,notified_at INTEGER,decided_at INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS schedule_notice_due ON schedule_notices(status,due_at);
CREATE INDEX IF NOT EXISTS schedule_notice_owner ON schedule_notices(owner_id,nominal_at);
CREATE TABLE IF NOT EXISTS schedule_notice_budgets(owner_id TEXT NOT NULL,day TEXT NOT NULL,calls INTEGER NOT NULL,tokens INTEGER NOT NULL,PRIMARY KEY(owner_id,day));
CREATE TABLE IF NOT EXISTS schedule_notice_attempts(notice_id TEXT NOT NULL REFERENCES schedule_notices(id),fence TEXT NOT NULL,PRIMARY KEY(notice_id,fence));
CREATE TABLE IF NOT EXISTS rest_diary_cycles(cycle_id TEXT PRIMARY KEY REFERENCES rest_cycles(id),frozen_at INTEGER NOT NULL,message_cutoff INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'frozen',error_code TEXT,started_at INTEGER,ended_at INTEGER);
CREATE TABLE IF NOT EXISTS rest_diary_sources(cycle_id TEXT NOT NULL REFERENCES rest_diary_cycles(cycle_id),policy_id TEXT NOT NULL REFERENCES diary_policies(id),policy_revision INTEGER NOT NULL,manager_id TEXT NOT NULL,source_key TEXT NOT NULL,owner_id TEXT NOT NULL,visibility TEXT NOT NULL,time_zone TEXT NOT NULL,allow_model INTEGER NOT NULL,floor INTEGER NOT NULL,from_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',cursor INTEGER NOT NULL DEFAULT 0,processed INTEGER NOT NULL DEFAULT 0,excluded INTEGER NOT NULL DEFAULT 0,error_code TEXT,updated_at INTEGER NOT NULL,PRIMARY KEY(cycle_id,policy_id));
CREATE INDEX IF NOT EXISTS rest_diary_source_actor ON rest_diary_sources(manager_id,cycle_id,status);
CREATE TABLE IF NOT EXISTS rest_diary_refs(cycle_id TEXT NOT NULL,policy_id TEXT NOT NULL,event_id TEXT NOT NULL REFERENCES diary_events(id),event_revision INTEGER NOT NULL,happened_at INTEGER NOT NULL,PRIMARY KEY(cycle_id,policy_id,event_id),FOREIGN KEY(cycle_id,policy_id) REFERENCES rest_diary_sources(cycle_id,policy_id));
CREATE TABLE IF NOT EXISTS rest_diary_messages(cycle_id TEXT NOT NULL,policy_id TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES messages(id),sequence INTEGER NOT NULL,happened_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',error_code TEXT,PRIMARY KEY(cycle_id,policy_id,message_id),FOREIGN KEY(cycle_id,policy_id) REFERENCES rest_diary_sources(cycle_id,policy_id));
CREATE INDEX IF NOT EXISTS rest_diary_message_cursor ON rest_diary_messages(cycle_id,policy_id,sequence);
CREATE TABLE IF NOT EXISTS rest_diary_parts(cycle_id TEXT NOT NULL,policy_id TEXT NOT NULL,message_id TEXT NOT NULL,part_id TEXT NOT NULL REFERENCES delivery_parts(id),sent_at INTEGER NOT NULL,PRIMARY KEY(cycle_id,policy_id,message_id,part_id));
CREATE TABLE IF NOT EXISTS rest_diary_claims(cycle_id TEXT NOT NULL,entry_id TEXT NOT NULL,expected_revision INTEGER NOT NULL,base_fingerprint TEXT,owned_revision INTEGER,owned_fingerprint TEXT,PRIMARY KEY(cycle_id,entry_id));
CREATE TABLE IF NOT EXISTS rest_diary_targets(cycle_id TEXT NOT NULL,policy_id TEXT NOT NULL,period TEXT NOT NULL,date TEXT NOT NULL,entry_id TEXT,state TEXT NOT NULL,error_code TEXT,PRIMARY KEY(cycle_id,policy_id,period,date),FOREIGN KEY(cycle_id,policy_id) REFERENCES rest_diary_sources(cycle_id,policy_id));
CREATE TABLE IF NOT EXISTS diary_version_cutoffs(entry_id TEXT NOT NULL REFERENCES diary_entries(id),revision INTEGER NOT NULL,cycle_id TEXT NOT NULL REFERENCES rest_diary_cycles(cycle_id),as_of INTEGER NOT NULL,PRIMARY KEY(entry_id,revision));

CREATE INDEX IF NOT EXISTS rest_diary_target_task ON rest_diary_targets(cycle_id,entry_id);
CREATE TABLE IF NOT EXISTS rest_diary_plan_state(cycle_id TEXT NOT NULL,policy_id TEXT NOT NULL,ref_cursor INTEGER NOT NULL DEFAULT 0,claim_cursor INTEGER NOT NULL DEFAULT 0,refs_done INTEGER NOT NULL DEFAULT 0,claims_done INTEGER NOT NULL DEFAULT 0,seeded INTEGER NOT NULL DEFAULT 0,turn INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(cycle_id,policy_id),FOREIGN KEY(cycle_id,policy_id) REFERENCES rest_diary_sources(cycle_id,policy_id));
CREATE TABLE IF NOT EXISTS rest_diary_requests(cycle_id TEXT NOT NULL,policy_id TEXT NOT NULL,period TEXT NOT NULL,date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',PRIMARY KEY(cycle_id,policy_id,period,date),FOREIGN KEY(cycle_id,policy_id) REFERENCES rest_diary_sources(cycle_id,policy_id));
CREATE INDEX IF NOT EXISTS rest_diary_request_queue ON rest_diary_requests(cycle_id,policy_id,status,period,date);
CREATE INDEX IF NOT EXISTS rest_diary_ref_time ON rest_diary_refs(cycle_id,policy_id,happened_at);
CREATE TABLE IF NOT EXISTS diary_record_imports(record_id TEXT PRIMARY KEY REFERENCES records(id),record_revision INTEGER NOT NULL,state TEXT NOT NULL,reason_code TEXT,event_id TEXT REFERENCES diary_events(id),event_revision INTEGER,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rest_diary_records(cycle_id TEXT NOT NULL,policy_id TEXT NOT NULL,record_id TEXT NOT NULL REFERENCES records(id),record_revision INTEGER NOT NULL,sequence INTEGER NOT NULL,happened_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',error_code TEXT,PRIMARY KEY(cycle_id,policy_id,record_id),FOREIGN KEY(cycle_id,policy_id) REFERENCES rest_diary_sources(cycle_id,policy_id));
CREATE INDEX IF NOT EXISTS rest_diary_record_cursor ON rest_diary_records(cycle_id,policy_id,status,sequence);
CREATE TABLE IF NOT EXISTS diary_unit_fragments(entry_id TEXT NOT NULL REFERENCES diary_entries(id),entry_revision INTEGER NOT NULL,outer_level INTEGER NOT NULL,unit_index INTEGER NOT NULL,sub_level INTEGER NOT NULL,ordinal INTEGER NOT NULL,unit_start INTEGER NOT NULL,unit_end INTEGER NOT NULL,total_units INTEGER NOT NULL,source_digest TEXT NOT NULL,input_digest TEXT NOT NULL,facts TEXT,feelings TEXT,model TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(entry_id,entry_revision,outer_level,unit_index,sub_level,ordinal));
